// Función para obtener la estación local basada en el país/ciudad del usuario
export function getLocalStation(userCountryCode: string, userCity: string): LocalQuaweStation | null {
  const byCountry = localQuaweStations.find((s) => s.countryCode === userCountryCode);
  if (byCountry) return byCountry;

  const byCity = localQuaweStations.find(
    (s) => s.city.toLowerCase() === userCity.toLowerCase()
  );
  if (byCity) return byCity;

  return null;
}

// Función para obtener todas las estaciones locales
export function getAllLocalStations(): LocalQuaweStation[] {
  return localQuaweStations;
}

// Estadísticas totales de la red Quawe
export const networkStats = {
  totalCities: localQuaweStations.length,
  totalPopulation: localQuaweStations.reduce((sum, s) => sum + s.population, 0),
  totalListeners: localQuaweStations.reduce((sum, s) => sum + s.station.clickcount, 0),
  countries: [...new Set(localQuaweStations.map((s) => s.country))].length,
};
